// Applies a validated brain result with the company policy read from the
// central store (a fixture here). Domain events are real effects and are
// applied idempotently; the post-appointment pause comes only from the
// policy and covers every channel of the conversation where it happened.
const policy = { pause_after_appointment: true, policy_version: 1 };
const result = {
  actions: [
    { action_id: 'synthetic-a1', sequence: 1, kind: 'reply' },
    { action_id: 'synthetic-a2', sequence: 2, kind: 'appointment_confirmation', source_ref: 'synthetic-appointment-1' },
  ],
  domain_events: [{ type: 'appointment.confirmed', appointment_ref: 'synthetic-appointment-1', attested_by_tool: true }],
};
const confirmations = result.actions.filter(a => a.kind === 'appointment_confirmation');
const lastSequence = Math.max(...result.actions.map(a => a.sequence));
const confirmationValid = confirmations.length <= 1 && confirmations.every(a =>
  a.sequence === lastSequence &&
  result.domain_events.some(e => e.type === 'appointment.confirmed' && e.appointment_ref === a.source_ref && e.attested_by_tool));
const unchangedSinceRequest = true;
const appointmentBlockCreated = policy.pause_after_appointment && result.domain_events.some(e => e.type === 'appointment.confirmed');
let actions = result.actions;
if (appointmentBlockCreated) actions = actions.filter(a => a.kind === 'appointment_confirmation');
actions = actions.map((a, index) => ({ ...a, sequence: index + 1, rebased_on_own_events: unchangedSinceRequest }));
return [{ json: { accepted: confirmationValid, invocation_checked: true, capabilities_checked: true, tool_payload_private: true, policy_source: 'central_company_policy', pause_after_appointment: policy.pause_after_appointment, appointment_block_created: appointmentBlockCreated, single_confirmation_only: appointmentBlockCreated, superseded_context_patch_applied: false, actions, simulated: true } }];
